{
  "restated_question": "Throughout the week of Oct 18–24, 2026, the NWS gauge at Oliver Lock and Dam (TODA1) reported daily mean flows ~300–400 cfs higher than the USGS gauge at Northport (02465000), ~1 km upstream. Which source should a forecaster trust, and what causes the systematic difference?",
  "hypotheses": [
    {
      "id": "H1",
      "claim": "The NWS Oliver flow is derived from tailwater stage using a rating curve that is biased high (or the USGS Northport rating is biased low); the two gauges are at different hydraulic control points (pool vs. tailwater), so their stage–flow relationships differ, and the ~300–400 cfs daily-mean gap persists even with zero rain and negligible pool-stage change, ruling out storage as the explanation."
    },
    {
      "id": "H2",
      "claim": "USGS Oliver tailwater stage (02465005) and NWS Oliver tailwater stage (TODA1) come from the same physical sensor and match hour-for-hour, but the agencies convert that identical stage to different flows, proving the disagreement is in the stage-to-flow conversion, not the stage measurement."
    },
    {
      "id": "H3",
      "claim": "The daily hydropeaking pulse at USGS Northport recurs at the same local hour (21:00 CDT on Oct 18–22, shifting to 19:00 CDT on Oct 23–24) with zero rainfall, confirming it is driven by scheduled hydropower releases at Holt Dam; the pool re-regulates these pulses, so the daily mean flow at Northport (upstream pool) should equal the daily mean release at Oliver (downstream tailwater) unless a rating curve is biased."
    }
  ],
  "checks": [
    {
      "id": "C1",
      "hypothesis": "H1",
      "purpose": "Quantify the daily mean flow difference between USGS Northport and NWS Oliver over the 6 full local days (Oct 19–24) and compare it to the daily pool-stage change at Northport; if stage change is negligible, the flow gap cannot be explained by storage and must be a rating-curve or hydraulic-control difference.",
      "how": "SELECT local_day, AVG(usgs_northport_cfs) AS mean_usgs_cfs, AVG(nws_oliver_cfs) AS mean_nws_cfs, AVG(nws_oliver_cfs) - AVG(usgs_northport_cfs) AS diff_cfs, MAX(usgs_northport_stage_ft) - MIN(usgs_northport_stage_ft) AS stage_change_ft FROM (SELECT hr_utc, usgs_northport_cfs, nws_oliver_cfs, usgs_northport_stage_ft, to_date(from_utc_timestamp(to_timestamp(hr_utc, 'yyyy-MM-dd HH:mm'), 'America/Chicago')) AS local_day FROM water.hourly_compare WHERE hr_utc >= '2026-10-19 05:00' AND hr_utc < '2026-10-25 05:00' AND usgs_northport_cfs IS NOT NULL AND nws_oliver_cfs IS NOT NULL) t GROUP BY local_day ORDER BY local_day"
    },
    {
      "id": "C2",
      "hypothesis": "H2",
      "purpose": "Verify that USGS Oliver tailwater stage and NWS Oliver tailwater stage are identical hour-by-hour (same sensor) while their derived flows differ, proving the disagreement is in stage-to-flow conversion, not stage measurement.",
      "how": "SELECT hr_utc, usgs_oliver_tailwater_ft, nws_oliver_tailwater_ft, nws_oliver_cfs, usgs_northport_cfs FROM water.hourly_compare WHERE hr_utc BETWEEN '2026-10-18 06:00' AND '2026-10-25 06:00' AND usgs_oliver_tailwater_ft IS NOT NULL AND nws_oliver_tailwater_ft IS NOT NULL ORDER BY hr_utc LIMIT 200"
    },
    {
      "id": "C3",
      "hypothesis": "H3",
      "purpose": "Test whether the USGS Northport peak occurs at a consistent local hour across all available days (Oct 18–24) by extracting the CDT hour of the daily maximum 15-min peak; a recurring hour confirms scheduled hydropower releases.",
      "how": "SELECT local_day, peak_hour_cdt, MAX(usgs_northport_peak_cfs) AS max_peak_cfs FROM (SELECT hr_utc, usgs_northport_peak_cfs, to_date(from_utc_timestamp(to_timestamp(hr_utc, 'yyyy-MM-dd HH:mm'), 'America/Chicago')) AS local_day, hour(from_utc_timestamp(to_timestamp(hr_utc, 'yyyy-MM-dd HH:mm'), 'America/Chicago')) AS peak_hour_cdt FROM water.hourly_compare WHERE hr_utc BETWEEN '2026-10-18 06:00' AND '2026-10-25 06:00' AND usgs_northport_peak_cfs IS NOT NULL) t GROUP BY local_day, peak_hour_cdt ORDER BY local_day, max_peak_cfs DESC LIMIT 200"
    }
  ]
}
